CREATE TABLE IF NOT EXISTS io_data_subject_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, request_type ENUM('access','correction','objection','deletion_assessment','restriction','consent_withdrawal','other') NOT NULL DEFAULT 'other', subject_user_id BIGINT UNSIGNED NULL, subject_reference VARCHAR(100) NULL, description TEXT NOT NULL, status ENUM('received','triage','in_progress','awaiting_subject','awaiting_approval','completed','rejected','closed') NOT NULL DEFAULT 'received', priority ENUM('low','normal','high','urgent') NOT NULL DEFAULT 'normal', received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, due_date DATE NULL, assigned_to BIGINT UNSIGNED NULL, decision_summary TEXT NULL, completed_at DATETIME NULL, created_by BIGINT UNSIGNED NOT NULL, updated_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_io_req_status(status,due_date));
CREATE TABLE IF NOT EXISTS io_privacy_incidents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, incident_type ENUM('unauthorised_access','data_loss','wrong_recipient','disclosure','device_loss','malware','availability','other') NOT NULL DEFAULT 'other', severity ENUM('low','medium','high','critical') NOT NULL DEFAULT 'medium', summary VARCHAR(255) NOT NULL, details TEXT NOT NULL, affected_data_categories VARCHAR(500) NULL, affected_people_estimate INT UNSIGNED NULL, discovered_at DATETIME NULL, reported_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, containment_actions TEXT NULL, notification_assessment TEXT NULL, lessons_learned TEXT NULL, status ENUM('reported','triage','contained','investigating','monitoring','resolved','closed') NOT NULL DEFAULT 'reported', owner_user_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, updated_by BIGINT UNSIGNED NULL, resolved_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_io_incident_status(status,severity));
CREATE TABLE IF NOT EXISTS io_retention_reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, record_category VARCHAR(150) NOT NULL, source_table VARCHAR(150) NULL, retention_basis VARCHAR(255) NOT NULL, retention_period VARCHAR(100) NOT NULL, review_date DATE NULL, due_date DATE NULL, legal_hold TINYINT(1) NOT NULL DEFAULT 0, proposed_action ENUM('retain','archive','anonymise','delete','legal_hold_review','undecided') NOT NULL DEFAULT 'undecided', decision_notes TEXT NULL, status ENUM('pending','review','approved','deferred','completed') NOT NULL DEFAULT 'pending', reviewed_by BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, completed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_io_retention_due(status,due_date));
CREATE TABLE IF NOT EXISTS io_access_reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, review_name VARCHAR(180) NOT NULL, scope_description TEXT NOT NULL, review_period_start DATE NULL, review_period_end DATE NULL, due_date DATE NULL, status ENUM('pending','in_progress','approved','remediation_required','completed') NOT NULL DEFAULT 'pending', findings TEXT NULL, remediation_owner BIGINT UNSIGNED NULL, remediation_due_date DATE NULL, reviewed_by BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, completed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_io_access_review_status(status,due_date));
CREATE TABLE IF NOT EXISTS io_audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, subject_user_id BIGINT UNSIGNED NULL, entity_type VARCHAR(100) NULL, entity_id VARCHAR(100) NULL, purpose VARCHAR(255) NULL, outcome ENUM('success','denied','failure') NOT NULL DEFAULT 'success', ip_hash CHAR(64) NULL, metadata_json JSON NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_io_audit_actor(actor_user_id,created_at), KEY idx_io_audit_subject(subject_user_id,created_at));
